/**
 * Test listing resources with a given prefix.
 *
 * @throws RepositoryException
 */
@Test
public void testListResourcesByPrefix() throws RepositoryException {
    RepositoryConnection connection = repository.getConnection();
    try {
        // Part 1: unlimited listing; we test that the resources with correct prefix are contained and the
        // resources with incorrect prefix not
        List<String> resources1 = ImmutableList.copyOf(Iterables.transform(ResourceUtils.listResourcesByPrefix(connection, "http://localhost:8080/LMF/resource/h"), new Function<Resource, String>() {

            @Override
            public String apply(Resource input) {
                return input.stringValue();
            }
        }));
        // test if the result has the expected size
        Assert.assertEquals(1, resources1.size());
        // test if the result contains all resources that have been used as subject
        Assert.assertThat(resources1, hasItems("http://localhost:8080/LMF/resource/hans_meier"));
        Assert.assertThat(resources1, not(hasItems("http://localhost:8080/LMF/resource/sepp_huber", "http://localhost:8080/LMF/resource/anna_schmidt")));
        // Part 2: limited listing; check whether limit and offset work as expected
        List<String> resources2 = ImmutableList.copyOf(Iterables.transform(ResourceUtils.listResourcesByPrefix(connection, "http://localhost:8080/LMF/resource/", 0, 2), new Function<Resource, String>() {

            @Override
            public String apply(Resource input) {
                return input.stringValue();
            }
        }));
        // test if the result has the expected size
        Assert.assertEquals(2, resources2.size());
        // test if the result contains some of resources that have been used as subject
        Assert.assertThat(resources2, anyOf(hasItem("http://localhost:8080/LMF/resource/hans_meier"), hasItem("http://localhost:8080/LMF/resource/sepp_huber"), hasItem("http://localhost:8080/LMF/resource/anna_schmidt")));
        // increase offset by 2 (i.e. next batch of resources)
        List<String> resources3 = ImmutableList.copyOf(Iterables.transform(ResourceUtils.listResourcesByPrefix(connection, "http://localhost:8080/LMF/resource/", 2, 2), new Function<Resource, String>() {

            @Override
            public String apply(Resource input) {
                return input.stringValue();
            }
        }));
        // test if the result has the expected size
        Assert.assertEquals(1, resources3.size());
        // test if the result contains some of resources that have been used as subject
        Assert.assertThat(resources3, anyOf(hasItem("http://localhost:8080/LMF/resource/hans_meier"), hasItem("http://localhost:8080/LMF/resource/sepp_huber"), hasItem("http://localhost:8080/LMF/resource/anna_schmidt")));
    } finally {
        connection.close();
    }
}

