    // carry out SPARQL SELECT query, selecting all persons and their names foaf:known by s1; must be s2 and s3
    String selectQuery = ("PREFIX foaf:    <http://xmlns.com/foaf/0.1/>\n" + "SELECT ?p ?n " + "WHERE { <$1> foaf:knows ?p . " + "        ?p foaf:name ?n      }").replaceAll("\\$1", s1);
    given().header("Accept", "application/xml").header("Content-Type", "text/plain").body(selectQuery).expect().statusCode(200).header("Content-Type", containsString("application/sparql-results+xml")).body(hasXPath("/sparql/results/result/binding[@name='p']/uri", ns, isOneOf(s2, s3))).body(hasXPath("/sparql/results/result/binding[@name='n']/literal", ns, isOneOf(v2, v3))).when().post("/sparql/select");
