@Test
public void testSetConfiguration() throws IOException {
    // set my.key to the values "value1" and "value2"
    given().header("Content-Type", "application/json").content(mapper.writeValueAsString(Lists.newArrayList("value1", "value2"))).expect().statusCode(200).when().post("/config/data/mykey");
    // test whether configuration service has the key
    Assert.assertThat(configurationService.getListConfiguration("mykey"), hasItem("value1"));
    // test whether values appear when retrieving the key
    expect().statusCode(200).body("mykey", hasItems("value1", "value2")).when().get("/config/data/mykey");
    // test whether values appear in full list
    expect().statusCode(200).body("mykey.value", hasItems("value1", "value2")).when().get("/config/list");
    // test whether deleting returns OK
    expect().statusCode(200).when().delete("/config/data/mykey");
    // test whether values appear when retrieving the key
    expect().statusCode(404).when().get("/config/data/mykey");
}

